import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'

/**
 * A menu button's behavior: it opens on click, arrows move between items (opening the menu on their end of it from the
 * button), Home and End jump, Escape closes and returns focus to the button, Tab and a click outside close it.
 */
export function useMenu() {
  const open = ref(false)
  const root = ref<HTMLElement | null>(null)
  const trigger = ref<HTMLElement | null>(null)

  const items = () => [...(root.value?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]

  async function show(focus: 'first' | 'last' | 'none' = 'first') {
    open.value = true
    await nextTick()
    // Opened at the fold it would land out of sight, and the button would seem to do nothing.
    items()[0]?.closest('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
    if (focus === 'none') return
    const list = items()
    ;(focus === 'last' ? list.at(-1) : list[0])?.focus()
  }
  function close(refocus = false) {
    open.value = false
    if (refocus) trigger.value?.focus()
  }
  function toggle() {
    if (open.value) close()
    else void show('none')
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      void show(event.key === 'ArrowDown' ? 'first' : 'last')
    }
    else if (event.key === 'Escape' && open.value) {
      event.preventDefault()
      close(true)
    }
  }
  function onMenuKey(event: KeyboardEvent) {
    const list = items()
    const at = list.indexOf(document.activeElement as HTMLElement)
    if (event.key === 'Escape') {
      event.preventDefault()
      close(true)
    }
    else if (event.key === 'Tab') {
      close()
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const step = event.key === 'ArrowDown' ? 1 : -1
      list[(at + step + list.length) % list.length]?.focus()
    }
    else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault()
      ;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
    }
  }
  function outside(event: PointerEvent) {
    if (open.value && root.value && !root.value.contains(event.target as Node)) close()
  }
  onMounted(() => document.addEventListener('pointerdown', outside))
  onBeforeUnmount(() => document.removeEventListener('pointerdown', outside))

  return { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey }
}

'use client'
import { createContext, useEffect, useId, useImperativeHandle, useRef, type ReactNode, type Ref } from 'react'
import { useMenu } from '@/react/hooks/useMenu'
import { cn } from '@/react/lib/cn'

// A button that opens a short list of choices or actions (console2.css .v2-menu): a square panel in a hairline, no
// shadow, 4px inside; rows from MenuItem. It comes in over 160ms, a 4px drop (a rise when it opens upward), and not at
// all when opened from the keyboard. Arrows, Home, End, Escape, Tab and a click outside are handled (useMenu).
// `offset` moves the panel in from its edge. The trigger's content is `trigger` (a node, or a function of `open`),
// drawn as a secondary button unless `triggerClass` says otherwise. `defaultOpen` opens it with the page; `ref` gets
// { open, show, close } (Vue's exposed open and close); `onOpenChange` hears it open and close. `data-ds` names the
// root for a component built on it (Vue's falls through: <Menu data-ds="account-menu">).
export const MenuClose = createContext<() => void>(() => {})

export interface MenuHandle { open: boolean, show: (focus?: 'first' | 'last' | 'none') => void, close: (refocus?: boolean) => void }
export interface MenuProps {
  label: string
  up?: boolean
  align?: 'start' | 'end'
  width?: string
  offset?: string
  triggerClass?: string
  triggerLabel?: string
  trigger?: ReactNode | ((open: boolean) => ReactNode)
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  'data-ds'?: string
  className?: string
  children?: ReactNode
  ref?: Ref<MenuHandle>
}

export function Menu({ label, up, align = 'start', width = '264px', offset = '0px', triggerClass, triggerLabel, trigger: triggerContent, defaultOpen, onOpenChange, 'data-ds': ds = 'menu', className, children, ref }: MenuProps) {
  const { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey } = useMenu(defaultOpen)
  const report = useRef(onOpenChange)
  report.current = onOpenChange
  const was = useRef(open)
  useEffect(() => {
    if (was.current === open) return
    was.current = open
    report.current?.(open)
  }, [open])
  useImperativeHandle(ref, () => ({ open, show, close }), [open, show, close])
  const id = `menu-${useId()}`
  return (
    <MenuClose.Provider value={() => close(true)}>
      <style href="ds-menu" precedence="ds">{css}</style>
      <div data-ds={ds} ref={root} className={cn('relative inline-block', className)}>
        <button
          ref={trigger}
          type="button"
          className={triggerClass ?? 'inline-flex h-control-sm cursor-pointer items-center gap-1.5 border border-action-secondary-edge bg-surface px-2.5 text-meta leading-5 font-medium text-fg transition-[border-color,background-color] duration-120 ease-standard hover:border-action-secondary-edge-hover active:bg-surface-subtle aria-expanded:border-action-secondary-edge-hover max-md:h-control-touch max-md:text-ui'}
          aria-haspopup="menu"
          aria-expanded={open}
          aria-controls={id}
          aria-label={triggerLabel}
          onClick={toggle}
          onKeyDown={onTriggerKey}
        >
          {typeof triggerContent === 'function' ? triggerContent(open) : triggerContent}
        </button>
        {open && (
          <div
            id={id}
            className="ds-menu"
            data-up={up || undefined}
            style={{ width, [align === 'end' ? 'right' : 'left']: offset, [up ? 'bottom' : 'top']: 'calc(100% + 4px)' }}
            role="menu"
            aria-label={label}
            onKeyDown={onMenuKey}
          >
            {children}
          </div>
        )}
      </div>
    </MenuClose.Provider>
  )
}

export default Menu

const css = `
.ds-menu { position: absolute; z-index: 40; display: flex; flex-direction: column; padding: var(--ds-space-xs); border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); animation: ds-menu-in var(--ds-duration-glide) var(--ds-easing-standard) both; scroll-margin: 8px; }
.ds-menu[data-up] { animation-name: ds-menu-up; }
/* Opened from the keyboard, focus lands on a row at once: no animation. */
.ds-menu:has(:focus-visible) { animation: none; }
.ds-menu > * { flex-shrink: 0; }
@keyframes ds-menu-in { from { opacity: 0; transform: translateY(-4px); } }
@keyframes ds-menu-up { from { opacity: 0; transform: translateY(4px); } }
@media (prefers-reduced-motion: reduce) { .ds-menu { animation: none; } }
`

'use client'
import { useContext, type ReactNode } from 'react'
import { MenuClose } from '@/react/components/ui/Menu'

// One row of a Menu (console2.css .v2-menu-item): 32px (44px on phones), 13px, a 14px gutter that holds the 4px red
// square marker of the row under the pointer or focus, which also takes the paper fill. `current` sets it in medium
// weight; `danger` is Sign out's red. Put a 14px Lucide icon first (text-fg-muted), a count or a check last.
// Choosing it calls `onSelect` and closes the menu, unless `keepOpen`. `role` and `aria-checked` make it a radio or
// checkbox row (role="menuitemradio" aria-checked={picked}), as Vue's fall through to the button.
export interface MenuItemProps { href?: string, current?: boolean, danger?: boolean, disabled?: boolean, keepOpen?: boolean, onSelect?: () => void, role?: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox', 'aria-checked'?: boolean, className?: string, children?: ReactNode }

export function MenuItem({ href, current, danger, disabled, keepOpen, onSelect, role = 'menuitem', 'aria-checked': checked, className, children }: MenuItemProps) {
  const close = useContext(MenuClose)
  function choose() {
    onSelect?.()
    if (!keepOpen) close()
  }
  const shared = { 'data-ds': 'menu-item', role, 'aria-checked': checked, className: className ? `ds-menu-item ${className}` : 'ds-menu-item', 'aria-current': current ? 'true' as const : undefined, 'data-danger': danger || undefined, onClick: choose }
  return (
    <>
      <style href="ds-menu-item" precedence="ds">{css}</style>
      {href ? <a href={href} {...shared}>{children}</a> : <button type="button" disabled={disabled} {...shared}>{children}</button>}
    </>
  )
}

export default MenuItem

const css = `
.ds-menu-item { position: relative; display: flex; width: 100%; height: var(--ds-size-control-md); align-items: center; gap: var(--ds-space-md); padding: 0 10px 0 14px; color: var(--ds-color-fg); font-size: var(--ds-text-ui); text-align: left; outline: none; cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item::before { position: absolute; top: 50%; left: 5px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item:focus-visible { background: var(--ds-color-surface-subtle); }
.ds-menu-item:focus-visible::before { opacity: 1; }
@media (hover: hover) and (pointer: fine) {
  .ds-menu-item:hover { background: var(--ds-color-surface-subtle); }
  .ds-menu-item:hover::before { opacity: 1; }
  .ds-menu-item[data-danger]:hover { background: var(--ds-color-surface-danger); }
}
.ds-menu-item[aria-current="true"] { font-weight: var(--ds-font-weight-medium); }
.ds-menu-item:disabled { color: var(--ds-color-fg-muted); cursor: progress; }
.ds-menu-item[data-danger] { color: var(--ds-color-fg-danger); }
.ds-menu-item[data-danger]:focus-visible { background: var(--ds-color-surface-danger); }
@media (pointer: coarse), (max-width: 767px) { .ds-menu-item { height: auto; min-height: 44px; } }
`

import type { ReactNode } from 'react'

// A group's name in a Menu (console2.css .v2-menu-label): 12px muted, an optional tag at the end.
export function MenuLabel({ children }: { children?: ReactNode }) {
  return <p data-ds="menu-label" className="flex items-center justify-between gap-2 pt-1.5 pr-2.5 pb-1 pl-3.5 text-meta text-fg-muted">{children}</p>
}

export default MenuLabel

// A hairline between a Menu's groups, edge to edge (console2.css .v2-menu-sep).
export function MenuSeparator() {
  return <div data-ds="menu-separator" className="-mx-1 my-1 h-px bg-edge" role="separator" />
}

export default MenuSeparator

'use client'
import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react'

/**
 * A menu button's behavior: it opens on click, arrows move between items (opening the menu on their end of it from the
 * button), Home and End jump, Escape closes and returns focus to the button, Tab and a click outside close it.
 */
export function useMenu(initial = false) {
  const [open, setOpen] = useState(initial)
  const root = useRef<HTMLDivElement | null>(null)
  const trigger = useRef<HTMLButtonElement | null>(null)
  const pending = useRef<'first' | 'last' | 'none' | null>(null)
  // Each show() renders, so an arrow on the open menu's button still focuses a row (Vue's nextTick runs either way).
  const [, setShown] = useState(0)

  const items = () => [...(root.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]

  // After the menu renders: scroll it into view and focus the row asked for (Vue's nextTick).
  useEffect(() => {
    if (!open || !pending.current) return
    const focus = pending.current
    pending.current = null
    // Opened at the fold it would land out of sight, and the button would seem to do nothing.
    items()[0]?.closest('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
    if (focus === 'none') return
    const list = items()
    ;(focus === 'last' ? list.at(-1) : list[0])?.focus()
  })

  const show = useCallback((focus: 'first' | 'last' | 'none' = 'first') => {
    pending.current = focus
    setOpen(true)
    setShown(n => n + 1)
  }, [])
  const close = useCallback((refocus = false) => {
    setOpen(false)
    if (refocus) trigger.current?.focus()
  }, [])
  function toggle() {
    if (open) close()
    else show('none')
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      show(event.key === 'ArrowDown' ? 'first' : 'last')
    }
    else if (event.key === 'Escape' && open) {
      event.preventDefault()
      close(true)
    }
  }
  function onMenuKey(event: KeyboardEvent) {
    const list = items()
    const at = list.indexOf(document.activeElement as HTMLElement)
    if (event.key === 'Escape') {
      event.preventDefault()
      close(true)
    }
    else if (event.key === 'Tab') {
      close()
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const step = event.key === 'ArrowDown' ? 1 : -1
      list[(at + step + list.length) % list.length]?.focus()
    }
    else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault()
      ;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
    }
  }
  useEffect(() => {
    function outside(event: PointerEvent) {
      if (root.current && !root.current.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', outside)
    return () => document.removeEventListener('pointerdown', outside)
  }, [])

  return { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey }
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html, nothing, type PropertyValues } from 'lit'
import { styleMap } from 'lit/directives/style-map.js'
import { DsElement, define, uid } from '@/elements/lib/element'
import { CloseOnSelect, menuRows } from '@/elements/lib/menu'
import styles from 'virtual:tw'

// Menu.vue as <conare-menu>: a button that opens a short list of choices or actions (console2.css .v2-menu): a square
// panel in a hairline, no shadow, 4px inside; rows are <conare-menu-item>. It comes in over 160ms, a 4px drop (a rise
// when it opens upward), and not at all when opened from the keyboard. Arrows, Home, End, Escape, Tab and a click
// outside are handled (useMenu). The trigger: a <button slot="trigger"> you style yourself (Vue's triggerClass), or
// any other content in the `trigger` slot, drawn as a secondary button. `open` opens it (Vue's exposed open);
// show() and close() are Vue's useMenu calls.

/**
 * @summary A button that opens a short list of choices or actions.
 * @slot - The rows: <conare-menu-item>, <conare-menu-label>, <conare-menu-separator>.
 * @slot trigger - A <button> to use as the trigger, or the default trigger's content.
 * @fires open-change - It opened or closed (detail.value).
 */
export class Menu extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = {
		label: {},
		up: { type: Boolean },
		// Vue's `align`; an `align` attribute is also HTML's old alignment hint, which the browser draws as text-align.
		placement: {},
		width: {},
		offset: {},
		triggerLabel: { attribute: 'trigger-label' },
		open: { type: Boolean, reflect: true },
		instant: { state: true },
	}

	/** The menu's name for assistive tech. */
	label = ''
	/** Opens upward. */
	up = false
	/** The panel's edge: start, or end to open toward the start from the trigger's end (Vue's `align`). */
	placement: 'start' | 'end' = 'start'
	width = '264px'
	/** Moves the panel in from its edge. */
	offset = '0px'
	/** The default trigger's name, when its content has none. */
	triggerLabel?: string
	open = false
	private instant = false
	private panelId = uid('menu')
	private pending: 'first' | 'last' | 'none' | null = null

	/** A <button slot="trigger"> the page drew, or the default trigger in the shadow root. */
	constructor() {
		super()
		// A chosen row closes the menu and returns focus to the trigger.
		new CloseOnSelect(this, () => this.close(true))
	}

	private get trigger(): HTMLElement | null {
		const own = this.querySelector<HTMLElement>(':scope > button[slot="trigger"]')
		return own ?? this.renderRoot.querySelector<HTMLElement>('button[data-trigger]')
	}
	private items() {
		return menuRows(this)
	}

	show(focus: 'first' | 'last' | 'none' = 'first') {
		this.pending = focus
		this.instant = focus !== 'none'
		this.setOpen(true)
		// Already open (an arrow on the open menu's button), it still renders, and the row asked for takes focus.
		this.requestUpdate()
	}
	close(refocus = false) {
		this.setOpen(false)
		if (refocus) this.trigger?.focus()
	}
	private setOpen(open: boolean) {
		if (this.open === open) return
		this.open = open
		this.emit('open-change', { value: open })
	}
	private toggle = () => {
		if (this.open) this.close()
		else this.show('none')
	}
	private onTriggerKey = (event: KeyboardEvent) => {
		if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
			event.preventDefault()
			this.show(event.key === 'ArrowDown' ? 'first' : 'last')
		} else if (event.key === 'Escape' && this.open) {
			event.preventDefault()
			this.close(true)
		}
	}
	private onMenuKey = (event: KeyboardEvent) => {
		const list = this.items()
		const at = list.findIndex((i) => i.matches(':focus-within'))
		if (event.key === 'Escape') {
			event.preventDefault()
			this.close(true)
		} else if (event.key === 'Tab') {
			// Vue and React take the panel out of the page before the browser moves focus, so Tab from a row lands on the
			// trigger; here the rows stay in the page (unslotted), so the element puts focus there itself.
			if (!event.shiftKey) {
				event.preventDefault()
				this.close(true)
			} else this.close()
		} else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
			event.preventDefault()
			const step = event.key === 'ArrowDown' ? 1 : -1
			list[(at + step + list.length) % list.length]?.focus()
		} else if (event.key === 'Home' || event.key === 'End') {
			event.preventDefault()
			;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
		}
	}
	private outside = (event: PointerEvent) => {
		if (this.open && !event.composedPath().includes(this)) this.close()
	}

	connectedCallback() {
		super.connectedCallback()
		document.addEventListener('pointerdown', this.outside)
	}
	disconnectedCallback() {
		super.disconnectedCallback()
		document.removeEventListener('pointerdown', this.outside)
		this.wire(null)
	}

	// The page's own trigger button gets the menu button's attributes and handlers.
	private wired: HTMLElement | null = null
	private wire(button: HTMLElement | null) {
		if (this.wired && this.wired !== button) {
			this.wired.removeEventListener('click', this.toggle)
			this.wired.removeEventListener('keydown', this.onTriggerKey)
		}
		if (button && this.wired !== button) {
			button.addEventListener('click', this.toggle)
			button.addEventListener('keydown', this.onTriggerKey)
			button.setAttribute('aria-haspopup', 'menu')
		}
		this.wired = button
		if (button) {
			button.setAttribute('aria-expanded', String(this.open))
			if (this.triggerLabel) button.setAttribute('aria-label', this.triggerLabel)
		}
	}

	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		this.wire(this.querySelector<HTMLElement>(':scope > button[slot="trigger"]'))
		if (changed.has('open') && !this.open) this.instant = false
		const focus = this.pending
		this.pending = null
		if (!this.open || !focus) return
		// Opened at the fold it would land out of sight, and the button would seem to do nothing.
		this.renderRoot.querySelector('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
		if (focus === 'none') return
		const list = this.items()
		;(focus === 'last' ? list.at(-1) : list[0])?.focus()
	}

	render() {
		const own = !!this.querySelector(':scope > button[slot="trigger"]')
		const panel = this.open
			? html`<div id=${this.panelId} class="ds-menu" ?data-up=${this.up} ?data-instant=${this.instant} style=${styleMap({ width: this.width, [this.placement === 'end' ? 'right' : 'left']: this.offset, [this.up ? 'bottom' : 'top']: 'calc(100% + 4px)' })} role="menu" aria-label=${this.label} @keydown=${this.onMenuKey}><slot></slot></div>`
			: nothing
		const trigger = own
			? html`<slot name="trigger"></slot>`
			: html`<button data-trigger type="button" class="inline-flex h-control-sm cursor-pointer items-center gap-1.5 border border-action-secondary-edge bg-surface px-2.5 text-meta leading-5 font-medium text-fg transition-[border-color,background-color] duration-120 ease-standard hover:border-action-secondary-edge-hover active:bg-surface-subtle aria-expanded:border-action-secondary-edge-hover max-md:h-control-touch max-md:text-ui" aria-haspopup="menu" aria-expanded=${String(this.open)} aria-label=${this.triggerLabel ?? nothing} @click=${this.toggle} @keydown=${this.onTriggerKey}><slot name="trigger"></slot></button>`
		return html`${trigger}${panel}`
	}
}

define('menu', Menu)

/* The host is the menu's box (Menu.vue's root div: relative inline-block), so a class on <conare-menu> lands on it as
   a class on <Menu> does. */
:host { @apply relative inline-block; }
/* Menu.vue's <style>. Opened from the keyboard, focus lands on a row at once: no animation. Vue reads that from
   :has(:focus-visible), which cannot see rows slotted from the page, so the element marks the panel data-instant. */
.ds-menu { position: absolute; z-index: 40; display: flex; flex-direction: column; padding: var(--ds-space-xs); border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); animation: ds-menu-in var(--ds-duration-glide) var(--ds-easing-standard) both; scroll-margin: 8px; }
.ds-menu[data-up] { animation-name: ds-menu-up; }
/* Opened from the keyboard, focus lands on a row at once: no animation. */
.ds-menu:has(:focus-visible) { animation: none; }
.ds-menu > * { flex-shrink: 0; }
@keyframes ds-menu-in { from { opacity: 0; transform: translateY(-4px); } }
@keyframes ds-menu-up { from { opacity: 0; transform: translateY(4px); } }
@media (prefers-reduced-motion: reduce) { .ds-menu { animation: none; } }
.ds-menu[data-instant] { animation: none; }

import { html, LitElement } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// MenuItem.vue as <conare-menu-item>: one row of a menu (console2.css .v2-menu-item): 32px (44px on phones), 13px, a
// 14px gutter that holds the 4px red square marker of the row under the pointer or focus, which also takes the paper
// fill. `current` sets it in medium weight; `danger` is Sign out's red. Put a 14px Lucide icon first, a count or a check
// last. Choosing it fires `select` and closes the menu around it (any element with lib/menu's CloseOnSelect: menu,
// context menu, menubar), unless `keep-open`. Vue's role and aria-checked fall through to the row's button; here
// `role` and `aria-checked` on the element move to its button (role="menuitemradio" aria-checked="true" for a radio
// row), or set the `itemRole` and `checked` properties.

/**
 * @summary One row of a menu.
 * @slot - The row: an icon, the label, a count or a check.
 * @fires select - The row was chosen.
 */
export class MenuItem extends DsElement {
	static styles = [DsElement.styles, styles]
	static shadowRootOptions = { ...LitElement.shadowRootOptions, delegatesFocus: true }
	static properties = { href: {}, current: { type: Boolean }, danger: { type: Boolean }, disabled: { type: Boolean, reflect: true }, keepOpen: { type: Boolean, attribute: 'keep-open' }, itemRole: { attribute: false }, checked: { attribute: false } }
	// role and aria-checked are read here and moved to the button, so the row is named once (a menuitemradio, checked or
	// not) and not twice.
	static get observedAttributes() {
		return [...super.observedAttributes, 'role', 'aria-checked']
	}

	href?: string
	/** The current choice, in medium weight. */
	current = false
	/** Sign out's red. */
	danger = false
	disabled = false
	/** Choosing it leaves the menu open. */
	keepOpen = false
	/** The button's role: menuitem, or menuitemradio and menuitemcheckbox (the `role` attribute). */
	itemRole = 'menuitem'
	/** A radio or checkbox row's state (the `aria-checked` attribute). */
	checked?: boolean

	attributeChangedCallback(name: string, old: string | null, value: string | null) {
		if (name === 'role' || name === 'aria-checked') {
			if (value === null) return
			if (name === 'role') this.itemRole = value
			else this.checked = value === 'true'
			this.removeAttribute(name)
			return
		}
		super.attributeChangedCallback(name, old, value)
	}

	private choose = () => {
		this.emit('select')
	}

	render() {
		const current = this.current ? 'true' : undefined
		const checked = this.checked === undefined ? undefined : String(this.checked)
		return this.href
			? html`<a data-ds="menu-item" href=${this.href} role=${this.itemRole} class="ds-menu-item" aria-current=${ifDefined(current)} aria-checked=${ifDefined(checked)} ?data-danger=${this.danger} @click=${this.choose}><slot></slot></a>`
			: html`<button data-ds="menu-item" type="button" role=${this.itemRole} class="ds-menu-item" aria-current=${ifDefined(current)} aria-checked=${ifDefined(checked)} ?data-danger=${this.danger} ?disabled=${this.disabled} @click=${this.choose}><slot></slot></button>`
	}
}

define('menu-item', MenuItem)

/* MenuItem.vue's <style>. A row is a flex item of the panel that does not shrink (Menu.vue's .ds-menu > *). */
.ds-menu-item { position: relative; display: flex; width: 100%; height: var(--ds-size-control-md); align-items: center; gap: var(--ds-space-md); padding: 0 10px 0 14px; color: var(--ds-color-fg); font-size: var(--ds-text-ui); text-align: left; outline: none; cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item::before { position: absolute; top: 50%; left: 5px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item:focus-visible { background: var(--ds-color-surface-subtle); }
.ds-menu-item:focus-visible::before { opacity: 1; }
@media (hover: hover) and (pointer: fine) {
  .ds-menu-item:hover { background: var(--ds-color-surface-subtle); }
  .ds-menu-item:hover::before { opacity: 1; }
  .ds-menu-item[data-danger]:hover { background: var(--ds-color-surface-danger); }
}
.ds-menu-item[aria-current="true"] { font-weight: var(--ds-font-weight-medium); }
.ds-menu-item:disabled { color: var(--ds-color-fg-muted); cursor: progress; }
.ds-menu-item[data-danger] { color: var(--ds-color-fg-danger); }
.ds-menu-item[data-danger]:focus-visible { background: var(--ds-color-surface-danger); }
@media (pointer: coarse), (max-width: 767px) { .ds-menu-item { height: auto; min-height: 44px; } }
.ds-menu-item { flex-shrink: 0; }

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// MenuLabel.vue as <conare-menu-label>: a group's name in a menu (console2.css .v2-menu-label): 12px muted, an
// optional tag at the end.

/**
 * @summary A group's name in a menu.
 * @slot - The name, and a tag if any.
 */
export class MenuLabel extends DsElement {
	static styles = [DsElement.styles, styles]
	render() {
		return html`<p data-ds="menu-label" class="flex items-center justify-between gap-2 pt-1.5 pr-2.5 pb-1 pl-3.5 text-meta text-fg-muted"><slot></slot></p>`
	}
}

define('menu-label', MenuLabel)

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// MenuSeparator.vue as <conare-menu-separator>: a hairline between a menu's groups, edge to edge
// (console2.css .v2-menu-sep).

/** @summary A hairline between a menu's groups. */
export class MenuSeparator extends DsElement {
	static styles = [DsElement.styles, styles]
	render() {
		return html`<div data-ds="menu-separator" class="-mx-1 my-1 h-px bg-edge" role="separator"></div>`
	}
}

define('menu-separator', MenuSeparator)
